package cryptosquare

import (
	"math"
	"strings"
	"unicode"
)

// Encode normalizes the plaintext (lower-casing and removing non-alphanumeric
// characters), lays it out in a rectangle as square as possible, and outputs
// the rectangle read down the columns, with each column as a space-separated
// chunk of length r (padded with trailing spaces where needed).
func Encode(pt string) string {
	var b strings.Builder
	for _, r := range pt {
		if unicode.IsLetter(r) || unicode.IsDigit(r) {
			b.WriteRune(unicode.ToLower(r))
		}
	}
	n := b.Len()
	if n == 0 {
		return ""
	}

	c := int(math.Ceil(math.Sqrt(float64(n))))
	r := int(math.Ceil(float64(n) / float64(c)))

	// Build the grid, padding the tail with spaces.
	grid := make([]byte, r*c)
	s := b.String()
	for i := 0; i < r*c; i++ {
		if i < n {
			grid[i] = s[i]
		} else {
			grid[i] = ' '
		}
	}

	// Read down the columns.
	var out strings.Builder
	for j := 0; j < c; j++ {
		if j > 0 {
			out.WriteByte(' ')
		}
		for i := 0; i < r; i++ {
			out.WriteByte(grid[i*c+j])
		}
	}
	return out.String()
}

